(() => {
const $=id=>document.getElementById(id);let user=null,dirty=false,offset=0,messageController=null,selectedContact=null;
const make=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
async function api(path,body){const r=await fetch('/retorno/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Não foi possível concluir.');return d;}
function expand(text,name){return text.replace(/\[nome cliente\]/gi,()=>name).replace(/\[nome (?:funcionário|funcionario|funcioonário|funcioonario)\]/gi,()=>user.name);}
async function load(){if(dirty&&!confirm('Há um atendimento ainda não salvo. Descartar o texto e atualizar?'))return;const button=$('reload');button.disabled=true;try{const d=await api('contacts?offset='+offset);messageController?.abort();messageController=new AbortController();user=d.user;$('workspace').insertBefore($('message-editor'),$('products'));$('products').replaceChildren();selectedContact=null;$('message-editor').hidden=true;dirty=false;
for(const product of d.products){const section=make('section');section.className='card';section.append(make('h2',product.name),make('p',product.total+' contatos · Exibindo '+(product.total?product.offset+1:0)+' a '+(product.offset+product.contacts.length)));
const tableWrap=make('div');tableWrap.className='contact-table-wrap';const table=make('table');table.className='contact-table';const head=make('thead'),heading=make('tr');for(const label of ['Data','Nome','Telefone','Interesse / motivos','Observação','Status','Atendimento'])heading.append(make('th',label));head.append(heading);const tbody=make('tbody');table.append(head,tbody);tableWrap.append(table);section.append(tableWrap);const detailHost=make('div');section.append(detailHost);
for(const item of product.contacts){const card=make('article');card.className='contact contact-detail';card.hidden=true;card.id='contact-'+item.id;const title=make('h3',item.name),badge=make('span'),result=make('textarea'),save=make('button','Salvar atendimento'),feedback=make('p'),preview=make('p'),whatsapp=make('a','Abrir WhatsApp com mensagem'),phone=make('a','+'+item.phone),stamp=make('small');
const summaryBadge=make('span');const render=()=>{summaryBadge.className='badge'+(item.responded_at?' responded':'');summaryBadge.textContent=item.responded_at?'Respondido':'Pendente';badge.className='badge'+(item.responded_at?' responded':'');badge.textContent=item.responded_at?'Respondido':'Pendente';stamp.textContent=item.responded_at?(item.staff_name?item.staff_name+' · ':'')+new Date(item.responded_at).toLocaleString('pt-BR'):'';};render();
phone.href='tel:+'+item.phone;result.value=item.attendance_result||'';result.rows=3;result.maxLength=1000;result.setAttribute('aria-label','Resultado da negociação com '+item.name);result.placeholder='Registre o resultado da negociação';save.type='button';save.className='btn';save.disabled=true;feedback.setAttribute('role','status');preview.className='preview';whatsapp.className='btn orange';whatsapp.target='_blank';whatsapp.rel='noopener noreferrer';
const message=()=>{const text=expand($('message').value,item.name);preview.textContent=text;whatsapp.href='https://wa.me/'+item.phone+'?text='+encodeURIComponent(text);whatsapp.hidden=!text.trim();};message();$('message').addEventListener('input',message,{signal:messageController.signal});
result.addEventListener('input',()=>{card.dataset.dirty=String(result.value.trim()!==(item.attendance_result||''));dirty=!!document.querySelector('[data-dirty="true"]');save.disabled=!result.value.trim()||card.dataset.dirty!=='true';feedback.textContent=card.dataset.dirty==='true'?'Alterações ainda não salvas.':'';});
save.addEventListener('click',async()=>{save.disabled=true;result.disabled=true;feedback.textContent='Salvando…';try{const d=await api('attendance',{id:item.id,result:result.value});Object.assign(item,d);result.value=d.attendance_result;card.dataset.dirty='false';dirty=!!document.querySelector('[data-dirty="true"]');render();row.lastElementChild.textContent=item.attendance_result;feedback.textContent='Atendimento salvo.';}catch(e){feedback.textContent=e.message;}finally{result.disabled=false;save.disabled=!result.value.trim()||result.value.trim()===(item.attendance_result||'');}});
const close=make('button','Fechar atendimento');close.type='button';close.className='btn light';close.addEventListener('click',()=>{if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;result.value=item.attendance_result||'';card.dataset.dirty='false';dirty=false;save.disabled=true;feedback.textContent='';card.hidden=true;row.classList.remove('selected');open.setAttribute('aria-expanded','false');selectedContact=null;$('message-editor').hidden=true;});
card.append(close,title,badge,make('p',new Date(item.created_at).toLocaleString('pt-BR')),phone,make('p',item.reasons.map(k=>({'produto-caro':'Preço do produto alto','frete-caro':'Frete caro','prazo-longo':'Prazo de entrega longo',outro:'Outro motivo'})[k]||k).join(', ')),make('p',item.other||''),preview,whatsapp,make('h4','Resultado do atendimento'),result,save,stamp,feedback);detailHost.append(card);
const row=make('tr'),nameCell=make('td'),open=make('button',item.name);open.type='button';open.className='contact-open';open.setAttribute('aria-expanded','false');open.setAttribute('aria-controls',card.id);nameCell.append(open);const statusCell=make('td');statusCell.append(summaryBadge);const reasons=item.reasons.map(k=>({'produto-caro':'Preço do produto alto','frete-caro':'Frete caro','prazo-longo':'Prazo de entrega longo',outro:'Outro motivo'})[k]||k).join(', ');const phoneCell=make('td','+'+item.phone);row.append(make('td',new Date(item.created_at).toLocaleString('pt-BR')),nameCell,phoneCell,make('td',reasons),make('td',item.other||'—'),statusCell,make('td',item.attendance_result||'Ainda sem retorno'));tbody.append(row);
const select=()=>{if(selectedContact===card)return;if(dirty&&!confirm('Descartar alterações ainda não salvas e abrir outro contato?'))return;
for(const detail of document.querySelectorAll('.contact-detail')){detail.hidden=true;detail.dataset.dirty='false';}for(const button of document.querySelectorAll('.contact-open'))button.setAttribute('aria-expanded','false');for(const entry of document.querySelectorAll('.contact-table tbody tr'))entry.classList.remove('selected');
result.value=item.attendance_result||'';save.disabled=true;feedback.textContent='';dirty=false;selectedContact=card;card.hidden=false;row.classList.add('selected');open.setAttribute('aria-expanded','true');card.insertBefore($('message-editor'),preview);$('message-editor').hidden=false;message();card.scrollIntoView({behavior:'smooth',block:'start'});};open.addEventListener('click',select);row.addEventListener('click',event=>{if(event.target!==open)select();});}

if(!product.contacts.length)section.append(make('p','Nenhum contato recebido para este produto.'));const nav=make('div');nav.className='toolbar';for(const [label,next,disabled] of [['Anterior',Math.max(0,offset-50),offset===0],['Próxima',offset+50,offset+product.limit>=product.total]]){const b=make('button',label);b.className='btn light';b.disabled=disabled;b.addEventListener('click',()=>{if(dirty&&!confirm('Descartar atendimento não salvo e mudar de página?'))return;dirty=false;offset=next;load();});nav.append(b);}section.append(nav);$('products').append(section);}
$('feedback').textContent='Contatos atualizados.';
}catch(e){$('feedback').textContent=e.message;}finally{button.disabled=false;}}
async function enter(u){user=u;$('login').hidden=true;$('password-change').hidden=!user.must_change_password;if(user.must_change_password){$('workspace').hidden=true;$('panel-link').hidden=true;$('feedback').textContent='É necessário alterar a senha inicial.';return;}$('workspace').hidden=false;$('panel-link').hidden=user.role!=='A';$('staff').textContent=user.name+' · '+(user.role==='A'?'Administrador':'Colaborador');await load();}
$('login-form').addEventListener('submit',async e=>{e.preventDefault();e.submitter.disabled=true;try{const d=await api('login',{username:$('username').value,password:$('password').value});$('password').value='';await enter(d.user);}catch(error){$('feedback').textContent=error.message;}finally{e.submitter.disabled=false;}});
$('password-form').addEventListener('submit',async e=>{e.preventDefault();e.submitter.disabled=true;try{const d=await api('change-password',{current_password:$('current-password').value,new_password:$('new-password').value,confirm_password:$('confirm-password').value});$('password-form').reset();await enter(d.user);}catch(error){$('feedback').textContent=error.message;}finally{e.submitter.disabled=false;}});
$('password-logout').addEventListener('click',async()=>{try{await api('logout',{});location.reload();}catch(error){$('feedback').textContent=error.message;}});
$('reload').addEventListener('click',load);$('logout').addEventListener('click',async()=>{if(dirty&&!confirm('Descartar atendimento não salvo e sair?'))return;try{await api('logout',{});location.reload();}catch(e){$('feedback').textContent=e.message;}});
for(const b of document.querySelectorAll('[data-variable]'))b.addEventListener('click',()=>{const f=$('message');f.setRangeText(b.dataset.variable,f.selectionStart,f.selectionEnd,'end');f.dispatchEvent(new Event('input'));f.focus();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
api('session').then(d=>{if(d.authenticated)enter(d.user);}).catch(e=>$('feedback').textContent=e.message);
})();